import queue
import threading


class QueueWorker:
    def __init__(self, callback, num_threads=1, timeout=1.0):
        self.queue = queue.Queue()
        self.callback = callback
        self.num_threads = num_threads
        self.timeout = timeout
        self.threads = []
        self._running = False

    def start(self):
        self._running = True
        for _ in range(self.num_threads):
            t = threading.Thread(target=self._worker_loop, daemon=False)
            t.start()
            self.threads.append(t)

    def _worker_loop(self):
        while self._running:
            try:
                item = self.queue.get(timeout=self.timeout)
            except queue.Empty:
                continue

            if item is None:
                self.queue.task_done()
                break

            try:
                self.callback(item)
            except Exception:
                raise
            finally:
                self.queue.task_done()

    def put(self, item):
        self.queue.put(item)

    def stop(self):
        self._running = False
        for _ in range(self.num_threads):
            self.queue.put(None)
        for t in self.threads:
            t.join()

    def join(self):
        self.queue.join()
